  const questions = {};
  const question = (id, ...entry) => { questions[typeof id === 'number' ? `atlas-${id}` : id] = entry; };
  question(1, 'Egy kolléga elhisz egy szép választ egy Claude-nak soha be nem mutatott belső rendszerről. Mi legyen a következő lépés?', ['Használjuk, mert részletes.', 'Vessük össze belső dokumentációval vagy jogosult forrással.', 'Kérjük táblázatként.', 'Állítsuk lejjebb a hőmérsékletet bizonyítékként.'], 'A modell nem kapta meg a belső tényeket. Független bizonyíték kell; stílus és beállítás nem igazol helyességet.');
  question(2, 'Az API-prototípus máshogy válaszol, mint a claude.ai. Mit hasonlíts össze először?', ['Csak a kérés helyesírását.', 'Hogy az API eleve gyengébb-e.', 'Modellverziót, rendszerutasításokat, eszközöket és kontextust.', 'Mióta használja a fejlesztő a terméket.'], 'A termékkörnyezet megváltoztatja a bemenetet és képességeket. Azonos feltételek mellett mérj.');
  question(3, 'A beszállítói elemzés csak megismétli a táblázatot. Melyik kérés segít leginkább?', ['Elemezz erősebben.', 'Légy a világ legjobb elemzője.', 'Írj hosszabban.', 'Rangsorold a beszállítókat a jövő negyedévi szállítási kockázat és költség alapján, a kapott adatokra hivatkozva.'], 'Az utolsó kérés döntési szempontot és bizonyítékot ad. A szerep vagy a hossz nem definiálja a hasznosságot.');
  question(4, 'A jelentés tényei jók, de a címsorok következetlenek. Mi segít?', ['Néhány példa pontosan a kívánt címsorokkal és sorrenddel.', 'Véletlenszerű további források.', 'Nagybetűs figyelmeztetés.', 'Magasabb hőmérséklet.'], 'A példák megmutatják az elvárt szerkezetet. Az eredményt továbbra is ellenőrizni kell.');
  question(5, 'Válassz KÉT hasznos elemet egy ügyféltájékoztató feladatleírásához.', ['Közönség és cél.', 'A hiányzó kiadási tények kitalálása.', 'Elvárt hossz, hangnem és cselekvésre hívás.', 'Tökéletes pontosság követelése forrás nélkül.', 'Ugyanazon homályos kérés ismétlése.'], 'A célközönség és kimeneti feltételek végrehajtható útmutatást adnak. Hiányzó tényhez bizonyíték vagy jelzett bizonytalanság kell.');
  question(6, 'A tervezet elrejti, mit kell az olvasónak tennie. Mi a legjobb visszajelzés?', ['Próbáld újra.', 'A kért lépés kerüljön az első két mondatba, a háttér legyen egy bekezdés.', 'Felejts el minden korlátot.', 'Legyen lenyűgözőbb.'], 'A célzott visszajelzés megnevezi a hibát és a kívánt változást.');
  question(7, 'Egy vezetői anyag pontos piaci statisztikát idéz. Mitől közölhető?', ['Két generált válaszban szerepel.', 'A modell 98%-os bizonyosságot mond.', 'A valódi mérvadó forrással és annak kontextusával ellenőriztük.', 'Professzionálisnak látszik a hivatkozás.'], 'A független ellenőrzés a számot és jelentését is vizsgálja. Generált egyetértés ugyanazt a hibát ismételheti.');
  question(8, 'Hogyan ellenőrzöd egy összefoglaló teljességét?', ['Összevetem a forrás lényeges részeivel és rendelkezéseivel.', 'Csak megszámolom a szavakat.', 'Megnézem, van-e következtetés.', 'Megkérdezem az összefoglalót, kihagyott-e valamit.'], 'A fontos hiányokat a forrással való összehasonlítás tárja fel, nem a hossz vagy önellenőrzés.');
  question(9, 'A táblázat és a szöveg ellentmond. Mit teszel?', ['Automatikusan a táblázatnak hiszek.', 'Automatikusan a szövegnek hiszek.', 'Átlagolom az állításokat.', 'Mindkettőt ellenőrzöm a forrásban és javítom az eltérést.'], 'Bármelyik forma lehet hibás. Bizonyítékkal oldd fel az ellentmondást.');
  question(10, 'Mely KÉT kimenet igényel különösen gondos független ellenőrzést?', ['Valakinek tulajdonított pontos idézet.', 'Szépen formázott címsor.', 'Barátságos köszönés.', 'Lényeges állítás egy nagyon friss szabályozásról.', 'Rövid bekezdés hosszú helyett.'], 'Az idézet hitelessége és friss szakmai tények érdemi kockázatot hordoznak. A forma nem megbízható jel.');
  question(11, 'Két bocsánatkérő tervezet nyelvtanilag jó. Hogyan válassz?', ['A hosszabbat választom.', 'Elismerés, felelősségvállalás, jóvátétel és márkahang szerint összevetem.', 'Emberi review nélkül dönt a modell.', 'Összemásolom a két teljes szöveget.'], 'Közös szempontrendszer alapján hasonlíts; az érzékeny közlést továbbra is ember vállalja.');
  question(12, 'Azonos havi feladat, dokumentumok és szempontrendszer ismétlődik. Mi illik hozzá?', ['Mindig új, általános chat.', 'Projekt válogatott tudással és állandó utasításokkal.', 'Nagyobb kimeneti keret.', 'Fájlok örök megtanulása ismétléssel.'], 'A Projekt csökkenti az ismételt beállítást. Nem finomhangolás, és karbantartást igényel.');
  question(13, 'Egy újrahasználható ajánlatot sokszor módosítasz. Melyik forma jó?', ['Minden bekezdéshez új chat.', 'Minden körben követhetetlen új másolat.', 'Artifact vagy karbantartott dokumentum ellenőrzött változatokkal.', 'Egysoros válasz.'], 'A karbantartott munkadokumentum támogatja az átdolgozást és verziókövetést.');
  question(14, 'A piaci jelentéshez sok oldal friss forrása kell. Mivel kezdesz?', ['Kutatás vagy keresés hivatkozásokkal, majd ellenőrzés.', 'Csak a tanításból származó válasz.', 'Tavalyi jelentés kitalált frissítésekkel.', 'A legnagyobb kontextusablak forrás nélkül.'], 'Friss kutatáshoz aktuális bizonyíték kell; a talált hivatkozást is ellenőrizd.');
  question(15, 'Mit NEM garantál egy Projekt?', ['Helyet a referenciáknak.', 'Közös utasításokat ismétlődő feladathoz.', 'Kevesebb ismételt beállítást.', 'Korlátlan kontextust és tökéletes felidézést.'], 'A Projekt rendszerezi a kontextust, nem szünteti meg a korlátokat vagy tényhibákat.');
  question(16, 'Az ajánlatadó asszisztens tavalyi árakat használ. Mi a legjobb javítás?', ['Minden chatben ismételni, hogy ne tegye.', 'Több kimeneti token.', 'A régi források cseréje vagy kizárása az aktuális keresésből, rendszeres felülvizsgálattal.', 'Jelölés nélkül megtartani mindkét verziót.'], 'Az elavult adatforrást javítsd. Auditcélú régi verzió elkülönítve maradhat.');
  question(17, 'Melyik beállítás választja helyesen külön a viselkedést és bizonyítékot?', ['Hangnemi szabály az utasításban, aktuális katalógus a tudásban.', 'Katalógus az utasításban, szabály csak referenciafájlban.', 'Mindkettő egy múlt havi privát chatben.', 'Semmi, a modell automatikusan megtanulja a csapatot.'], 'Az utasítás viselkedést ír le, a tudás referenciatényeket ad.');
  question(18, 'Kétezer fájlból 18 releváns az ajánlatkészítéshez. Mi kerüljön az induló tudásba?', ['Minden fájl.', 'Csak a legrégebbiek.', 'Semmilyen referencia.', 'A releváns, aktuális fájlok azonosítható forrással és gazdával.'], 'A válogatott bizonyíték csökkenti a zajt és az elavult ellentmondást.');
  question(19, 'Mi előzi meg élő céges dokumentumok kapcsolását?', ['Előbb próba bizalmas adatokkal.', 'Engedélyezett használat, jogosultság, érzékenység és frissesség vizsgálata.', 'Közös adminfiók megosztása.', 'Frissítések letiltása.'], 'A connector kényelme nem mentesít az adatkezelési szabályok alól.');
  question(20, 'Mi a helyes beállítási sorrend?', ['Üres Projekt tesztje, aztán célválasztás.', 'Finomítás az első kimenet előtt.', 'Létrehozás, utasítás, válogatott forrás, próba, finomítás.', 'Minden feltöltése teszt nélkül.'], 'A beállítás után értelmes a próba; az eredmény alapján lehet finomítani.');
  question(21, 'A csapat újra és újra beilleszti ugyanazt a hangnemi szabályt. Hová kerüljön?', ['A Projekt állandó utasításaiba.', 'Felhasználónként más privát chatbe.', 'Csak a kész jelentésbe.', 'A modellnek el nem küldött képernyőképbe.'], 'A közös viselkedési beállítás csökkenti az ismétlést, de továbbra sem kikényszerített garancia.');
  question(22, 'Egy ellenőrzött tervezési döntés jövő hónapban is kell. Mi őrzi meg megbízhatóan?', ['Feltételezett emlékezet minden új chatben.', 'Böngészőlap korlátlan nyitva tartása.', 'Emlékezetből újraalkotás.', 'Ellenőrzött döntési összefoglaló jóváhagyott, tartós helyen.'], 'A tudatos tárolás megőrzi az eredményt a munkameneten túl is.');
  question(23, 'Minden dokumentumnál kinyerés, validáció és archiválás történik köztes ellenőrzéssel. Mi a jó alap?', ['Teljesen autonóm ügynökcsapat.', 'Rögzített munkafolyamat explicit lépésszerződésekkel.', 'Korlátlan egyetlen prompt.', 'Véletlen folyamatválasztás.'], 'Az ismert sorrend kódvezérelt munkafolyamatot indokol; autonómia nem szükséges.');
  question(24, 'A számlák többsége standard, a szokatlanhoz feltárás vagy ember kell. Mi illik?', ['Ügynök minden műveletre.', 'Mezőnként külön ügynök.', 'Normál munkafolyamat, korlátozott ügynök a kivételponton.', 'Reménykedés, hogy minden forma azonos.'], 'A hibrid a bizonytalanság helyére korlátozza az autonómiát.');
  question(25, 'A következő diagnosztikai lekérdezés mindig az új lelettől függ. Mely minta illik?', ['Korlátozott tervezés–művelet–megfigyelés ciklus.', 'Az összes elképzelhető lekérdezés előre rögzítve.', 'Egy fordításszerű hívás.', 'Véletlenszerű diagnózisköteg.'], 'A végrehajtás során kialakuló úthoz alkalmazkodó, korlátozott ügynök illik.');
  question(26, 'Egy nagy megfelelőségi prompt világosabb szöveggel is kihagy szabályokat. Mi a szerkezeti javítás?', ['Kétszer ismételni.', 'Csak hőmérsékletet csökkenteni.', 'Elrejteni a hiányzó részeket.', 'Kinyerés, szabálycsoportok vizsgálata, ellenőrzés, pontozás, szintézis.'], 'A külön ellenőrizhető lépések csökkentik a túlterhelést és mérhetővé teszik a lefedettséget.');
  question(27, 'Visszatérítés, címhiba és hiányzó jóváírás érkezik együtt. Hogyan szervezd?', ['Csak az elsőt oldd meg.', 'Külön ügykövetés, közös igazolt tények, független feltárás, egységes válasz.', 'Azonnal követelj három új ticketet.', 'Minden többügyes kérést automatikusan eszkalálj.'], 'A felbontás megőrzi a lefedettséget; függő módosításnál sorrend és engedély kell.');
  question(28, 'Mely sorrend ad megbízható vezetői összefoglalót?', ['Írás, célközönség, esetleg ellenőrzés.', 'Minden kinyerése cél nélkül.', 'Cél, releváns tények kinyerése, ellenőrzés, írás, finomítás.', 'Forrás csiszolása ellenőrzés nélkül.'], 'A cél irányítja a kinyerést, a tényellenőrzés megelőzi a további felhasználást.');
  question(29, 'Miben térjen el az ötletelés egy hivatalos projektdokumentumtól?', ['Ötletelésnél változatosság, hivatalos dokumentumnál szerkezet és korlátok.', 'Mindkettőnél ugyanaz a homályos kérés.', 'Ötletelésnél egyetlen válasz, hivatalosnál semmi szerkezet.', 'Mindkettőt kerülni kell.'], 'A kérés igazodjon a feltáró vagy döntésre összpontosító célhoz.');
