  question(70, 'A pipeline sémakövető JSON megállapításokat kér. Mit használjon?', ['Regexet szabad szövegen.', '--output-format json és --json-schema, a structured_output validált olvasásával.', 'Csak rövidségre kérést.', 'Képernyőképet.'], 'A JSON-boríték nem maga a findings-szerződés; a structured_output hordozza az alkalmazásadatot.');
  question(71, 'A „csak nagy bizalmú hibát jelents” sok fals pozitívot ad. Mi jobb?', ['Háromszor ismételni.', 'Indoklást elrejteni.', 'Hibakategóriák, kivételek és példák definiálása.', 'Minden gyanút kritikusnak nevezni.'], 'A konkrét döntési kritérium hasznosabb a kalibrálatlan önbizalomnál.');
  question(72, 'Miért vizsgáld a generált kódot friss, független kontextusban?', ['Csökkenti az előző generálási indokláshoz való kötődést.', 'Minden hibát garantáltan megtalál.', 'Feleslegessé teszi a tesztet.', 'Megszünteti az emberi merge-jóváhagyást.'], 'A függetlenség javítja a vizsgálatot, de nem ad bizonyosságot.');
